import { useRef } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";

gsap.registerPlugin(useGSAP);

export function FadeIn() {
  const container = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      gsap.from(".box", {
        y: {{y}},
        opacity: 0,
        duration: {{duration}},
        ease: "{{ease}}",
      });
    },
    { scope: container },
  );

  return (
    <div ref={container}>
      <div className="box">Hello</div>
    </div>
  );
}
